package com.savora.api; import com.savora.model.*; import com.savora.repo.*; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*;
@RestController @RequestMapping("/admin") public class AdminController {final RestaurantRepo restaurants;final FoodRepo foods;final CategoryRepo categories;final UserRepo users;final OrderRepo orders;public AdminController(RestaurantRepo r,FoodRepo f,CategoryRepo c,UserRepo u,OrderRepo o){restaurants=r;foods=f;categories=c;users=u;orders=o;}@GetMapping("/dashboard")Api<?> dashboard(){var all=orders.findAll();BigDecimal revenue=all.stream().filter(o->o.status==OrderStatus.DELIVERED).map(o->o.total).reduce(BigDecimal.ZERO,BigDecimal::add);return Api.ok(Map.of("restaurants",restaurants.count(),"foods",foods.count(),"users",users.count(),"orders",all.size(),"revenue",revenue,"recent",all.stream().limit(6).toList()));}@GetMapping("/restaurants")Api<?> restaurants(){return Api.ok(restaurants.findAll());}@PostMapping("/restaurants")Api<?> addRestaurant(@RequestBody Restaurant x){x.id=null;return Api.ok(restaurants.save(x));}@GetMapping("/foods")Api<?> foods(){return Api.ok(foods.findAll());}@PostMapping("/foods")Api<?> food(@RequestBody Food x){x.id=null;x.restaurant=restaurants.findById(x.restaurant.id).orElseThrow(()->new NoSuchElementException("Restaurant not found"));if(x.category!=null)x.category=categories.findById(x.category.id).orElseThrow(()->new NoSuchElementException("Category not found"));return Api.ok(foods.save(x));}@GetMapping("/categories")Api<?> categories(){return Api.ok(categories.findAll());}@PostMapping("/categories")Api<?> category(@RequestBody Category x){x.id=null;return Api.ok(categories.save(x));}}
